import { test,expect,type Page,type Locator } from '@playwright/test';
import { randomUUID } from 'node:crypto';
import { mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import { installAccountFixture,installDesktopBridge } from './account-fixture';
import { evidenceDirectory } from './evidence-directory';
import type { PublicationDocument,PublicationVersionInfo,PublicationVersion } from '../src/domain/publication';

const base='http://localhost:1457';
async function rpc<T>(command:string,args:Record<string,unknown>={}):Promise<T>{const reply=await fetch(base+'/rpc',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({command,args})}).then(r=>r.json());if(!reply.ok)throw new Error(JSON.stringify(reply.error));return reply.value;}
async function liftPublicationPage(page:Page,dialog:Locator){
  const handle=dialog.getByRole('button',{name:'拖动排序 第 1 页',exact:true});await expect(handle).toBeEnabled();await handle.hover();await handle.focus();await page.keyboard.press('Space');await expect(dialog.locator('.publication-page-item.is-dragging')).toHaveCount(1);
  // KeyboardSensor 在拿起事件之后注册文档监听；等下一次绘制再发送后续方向键。
  await page.evaluate(()=>new Promise<void>(resolve=>requestAnimationFrame(()=>resolve())));
}
async function publicationVisibleSelectionPoint(dialog:Locator){
  return dialog.locator('.publication-studio-papers [data-publication-kind][aria-pressed=true]').evaluateAll(nodes=>{
    for(const node of nodes){const rect=node.getBoundingClientRect();for(const [rx,ry]of [[.5,.5],[.25,.25],[.75,.75]]){const x=rect.left+rect.width*rx,y=rect.top+rect.height*ry;const hit=node.ownerDocument.elementFromPoint(x,y)?.closest('[data-publication-id]');if(hit?.getAttribute('data-publication-id')===node.getAttribute('data-publication-id'))return {x,y};}}
    throw new Error('没有可见的已选对象拖动位置');
  });
}
async function prepare(page:Page){
  await page.emulateMedia({reducedMotion:'reduce'});
  const errors:string[]=[],outside:string[]=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',message=>{if(message.type()==='error'&&/same key|Each child in a list|Encountered two children|Invalid hook|Cannot update a component/i.test(message.text()))errors.push(message.text());});await page.route('**/*',route=>{if(['localhost','127.0.0.1','[::1]'].includes(new URL(route.request().url()).hostname))return route.continue();outside.push(route.request().url());return route.abort();});
  await installAccountFixture(page,true);await installDesktopBridge(page,base);
  const {id:projectId}=await rpc<{id:string}>('create_project',{title:'出版版本 '+randomUUID().slice(0,6),brief:'记录版面变化，保留原图和已确认的版本'});const token=await rpc<string>('choose_import',{projectId});const jobId=await rpc<string>('import_photos',{projectId,selectionToken:token});
  await expect.poll(async()=>(await rpc<{status:string}>('get_import_job',{jobId})).status,{timeout:100000}).toBe('completed');
  const project=await rpc<{revision:number;photos:Array<{id:string}>}>('get_project',{projectId});const id=randomUUID();const approved=await rpc<{ok:boolean;error:unknown}>('execute_gui_command',{request:{commandId:id,idempotencyKey:id,projectId,expectedProjectRevision:project.revision,causationId:id,command:{type:'SetPhotoDecision',photoIds:project.photos.slice(0,3).map(p=>p.id),status:'keep'}}});expect(approved.ok,JSON.stringify(approved.error)).toBe(true);
  const hashes=await rpc('test_fixture_checksums');await page.goto('/#/project/'+projectId);await page.getByRole('button',{name:'出版物',exact:true}).click();await page.getByRole('textbox',{name:'出版物标题',exact:true}).fill('夜行 · 摄影书');await page.getByRole('button',{name:'创建',exact:true}).click();await expect(page.locator('.publication-card-head strong')).toHaveText('夜行 · 摄影书');await page.getByRole('button',{name:'从序列生成（3 张）',exact:true}).click();
  const pubs=await rpc<Array<{id:string}>>('pub_list',{projectId});const publicationId=pubs[0].id;const dialog=page.getByRole('dialog',{name:'版面与版本',exact:true});await expect(dialog.getByRole('button',{name:'选择照片框 1',exact:true})).toBeVisible();
  return {projectId,publicationId,dialog,hashes,errors,outside};
}

test('真实出版旅程：调整预览、保存版本、并排比较、确认恢复与重启保持',async({page})=>{
  const {projectId,publicationId,dialog,hashes,errors,outside}=await prepare(page);const original=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId});
  await dialog.getByRole('textbox',{name:'版本名称',exact:true}).fill('确认 A');await dialog.getByRole('button',{name:'保存版本',exact:true}).click();await expect(dialog.getByRole('status',{name:'版面状态',exact:true})).toHaveText('版本已保存。');
  const versions=await rpc<PublicationVersionInfo[]>('pub_versions',{projectId,publicationId,before:null});const saved=versions.find(v=>v.label==='确认 A')!;expect(saved).toBeTruthy();const frozen=await rpc<PublicationVersion>('pub_version',{projectId,publicationId,versionId:saved.id});
  await dialog.getByRole('button',{name:'选择照片框 1',exact:true}).click();await dialog.getByRole('spinbutton',{name:'宽度（mm）',exact:true}).fill('150');await dialog.getByRole('spinbutton',{name:'放大倍数',exact:true}).fill('1.4');
  expect((await rpc<PublicationDocument>('pub_layout',{projectId,publicationId})).layout).toEqual(original.layout);await dialog.getByRole('button',{name:'保存调整',exact:true}).click();await expect(dialog.getByRole('status',{name:'版面状态',exact:true})).toHaveText('版面调整已保存。');
  const changed=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId});expect(changed.layout.pages[0].frames[0].widthMm).toBe(150);expect(changed.layout.pages[0].frames[0].cropZoom).toBe(1.4);expect(changed.layout.pages.slice(1)).toEqual(original.layout.pages.slice(1));
  await dialog.getByRole('tab',{name:'版本记录',exact:true}).click();await dialog.getByRole('button',{name:/^确认 A/}).click();await expect(dialog.getByText('查看历史版面',{exact:true})).toBeVisible();await dialog.getByRole('button',{name:'与当前并排比较',exact:true}).click();await expect(dialog.locator('.publication-studio-paper')).toHaveCount(2);
  const directory=evidenceDirectory('publication-studio');await mkdir(directory,{recursive:true});await page.screenshot({path:resolve(directory,'compare-versions.png')});
  await dialog.getByRole('button',{name:'恢复此版本',exact:true}).click();expect((await rpc<PublicationDocument>('pub_layout',{projectId,publicationId})).layout).toEqual(changed.layout);await dialog.getByRole('group',{name:'确认恢复',exact:true}).getByRole('button',{name:'确认恢复',exact:true}).click();await expect(dialog.getByRole('status',{name:'版面状态',exact:true})).toHaveText('已恢复为新的版面版本。');
  const restored=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId});expect(restored.layout).toEqual(original.layout);expect(restored.revision).toBe(changed.revision+1);expect(await rpc('pub_version',{projectId,publicationId,versionId:saved.id})).toEqual(frozen);
  await dialog.getByRole('button',{name:'关闭对话框',exact:true}).click();await page.goto('about:blank');await rpc('test_process_restart');expect(await rpc('pub_layout',{projectId,publicationId})).toEqual(restored);
  await page.goto('/#/project/'+projectId);await page.getByRole('button',{name:'出版物',exact:true}).click();
  await page.getByRole('button',{name:'从序列生成（3 张）',exact:true}).click();
  const confirmation=page.getByRole('dialog',{name:'重新生成页面？',exact:true});await expect(confirmation).toBeVisible();expect(await rpc('pub_layout',{projectId,publicationId})).toEqual(restored);
  await confirmation.getByRole('button',{name:'重新生成',exact:true}).click();await expect(page.getByRole('dialog',{name:'版面与版本',exact:true})).toBeVisible();
  const regenerated=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId});expect(regenerated.revision).toBe(restored.revision+1);expect(regenerated.layout.pages).toHaveLength(4);expect(await rpc('pub_version',{projectId,publicationId,versionId:saved.id})).toEqual(frozen);
  expect(await rpc('test_fixture_checksums')).toEqual(hashes);expect(errors).toEqual([]);expect(outside).toEqual([]);
});

test('真实保存回执丢失：页面重开只确认原请求，不重复生成版本',async({page})=>{
  const {projectId,publicationId,dialog,hashes,errors,outside}=await prepare(page);let lost=false;let commandId='';
  await page.route(base+'/rpc',async route=>{const data=route.request().postDataJSON();if(!lost&&data.command==='pub_execute'&&data.args.request.operations[0].action.type==='CaptureVersion'){lost=true;commandId=data.args.request.commandId;const reply=await(await route.fetch()).json();expect(reply.ok).toBe(true);await route.fulfill({json:{ok:false,error:{code:'DATABASE',message:'lost after commit'}}});}else await route.fallback();});
  await dialog.getByRole('textbox',{name:'版本名称',exact:true}).fill('待确认版');await dialog.getByRole('button',{name:'保存版本',exact:true}).click();await expect(dialog.getByRole('button',{name:'确认上次保存',exact:true})).toBeVisible();expect(lost).toBe(true);
  const before=await rpc<PublicationVersionInfo[]>('pub_versions',{projectId,publicationId,before:null});expect(before.filter(v=>v.label==='待确认版')).toHaveLength(1);expect(before[0].id).toBe(commandId);
  await page.reload();await page.getByRole('button',{name:'出版物',exact:true}).click();await page.getByRole('button',{name:'确认上次保存',exact:true}).click();await expect(page.getByRole('button',{name:'确认上次保存',exact:true})).toHaveCount(0);
  expect(await rpc('pub_versions',{projectId,publicationId,before:null})).toEqual(before);expect(await page.evaluate(()=>Object.keys(localStorage).filter(key=>key.startsWith('focalroom.publication.pending.')))).toEqual([]);expect(await rpc('test_fixture_checksums')).toEqual(hashes);expect(errors).toEqual([]);expect(outside).toEqual([]);
});

test('工作区分离：画布明确选图来源，共享评片登录引导不带选片栏',async({page})=>{
  const {projectId,dialog,hashes,errors,outside}=await prepare(page);
  await dialog.getByRole('button',{name:'关闭对话框',exact:true}).click();
  await page.getByRole('button',{name:'选片工作台',exact:true}).click();
  await page.getByTestId('photo-5').getByRole('button',{name:/^查看第/}).click();
  const original=await rpc<{photos:unknown[];sequence:string[]}>('get_project',{projectId});
  await page.getByRole('button',{name:'叙事画布',exact:true}).click();
  await expect(page.locator('.toolbar')).toHaveCount(0);
  await expect(page.locator('.inspector')).toHaveCount(0);
  await expect(page.locator('.selection-dock')).toHaveCount(0);
  await page.getByRole('button',{name:'新建画布',exact:true}).click();
  await page.getByRole('button',{name:'添加照片',exact:true}).click();
  const picker=page.getByRole('dialog',{name:'添加照片',exact:true});
  await expect(picker.getByRole('button',{name:'作品序列 · 3',exact:true})).toHaveAttribute('aria-pressed','true');
  await expect(picker.getByRole('checkbox')).toHaveCount(3);
  await picker.getByRole('button',{name:'工作台选区 · 1',exact:true}).click();
  await expect(picker.getByRole('button',{name:'工作台选区 · 1',exact:true})).toHaveAttribute('aria-pressed','true');
  await expect(picker.getByRole('button',{name:'作品序列 · 3',exact:true})).toHaveAttribute('aria-pressed','false');
  await expect(picker.getByRole('checkbox')).toHaveCount(1);
  const directory=evidenceDirectory('workspace-clarity');await mkdir(directory,{recursive:true});
  await page.screenshot({path:resolve(directory,'canvas-photo-source.png')});
  await picker.getByRole('checkbox').check();
  await picker.getByRole('button',{name:'添加 1 张到画布',exact:true}).click();
  await expect(picker).toHaveCount(0);
  await expect(page.locator('.canvas-photo-node')).toHaveCount(1);
  const after=await rpc<{photos:unknown[];sequence:string[]}>('get_project',{projectId});expect(after.photos).toEqual(original.photos);expect(after.sequence).toEqual(original.sequence);
  await page.getByRole('button',{name:'共享评片',exact:true}).click();
  await expect(page.getByRole('button',{name:'共享评片',exact:true})).toHaveAttribute('aria-current','page');
  await expect(page.getByRole('button',{name:'叙事画布',exact:true})).not.toHaveAttribute('aria-current','page');
  await expect(page.getByRole('heading',{name:'邀请他人审稿',exact:true})).toBeVisible();
  await expect(page.locator('.toolbar')).toHaveCount(0);
  await expect(page.locator('.inspector')).toHaveCount(0);
  await page.screenshot({path:resolve(directory,'shared-review.png')});
  await page.getByRole('button',{name:'登录并共享',exact:true}).click();
  await expect(page.getByRole('dialog',{name:'登录 FocalRoom',exact:true})).toBeVisible();
  expect(await rpc('test_fixture_checksums')).toEqual(hashes);expect(errors).toEqual([]);expect(outside).toEqual([]);
});

test('画布照片去重与移除：旧重复布局可整组移除、撤销并重新添加，原图与序列保持',async({page})=>{
  const {projectId,dialog,hashes,errors,outside}=await prepare(page);
  await dialog.getByRole('button',{name:'关闭对话框',exact:true}).click();
  const before=await rpc<{photos:unknown[];sequence:string[]}>('get_project',{projectId});
  await page.getByRole('button',{name:'叙事画布',exact:true}).click();
  await page.getByRole('button',{name:'新建画布',exact:true}).click();
  const choose=page.getByRole('combobox',{name:'选择画布'});await expect(choose).toHaveValue(/.+/);
  const boardId=await choose.inputValue();
  await page.getByRole('button',{name:'添加照片',exact:true}).click();
  const picker=page.getByRole('dialog',{name:'添加照片',exact:true});
  await picker.getByRole('checkbox').first().check();
  await picker.getByRole('button',{name:'添加 1 张到画布',exact:true}).click();
  await expect(page.locator('.canvas-photo-node')).toHaveCount(1);
  await page.getByRole('button',{name:'添加照片',exact:true}).click();
  await expect(picker.getByRole('checkbox').first()).toBeDisabled();
  await expect(picker.getByText('已在画布',{exact:true})).toHaveCount(1);
  await picker.getByRole('button',{name:'取消',exact:true}).click();
  type Snapshot={board:{revision:number};nodes:Array<{id:string;assetId:string|null;x:number;y:number}>;photoSources:Array<{photoId:string;assetId:string}>};
  const original=await rpc<Snapshot>('canvas_snapshot',{projectId,boardId});
  expect(original.photoSources[0].photoId).toBe(before.sequence[0]);
  expect(original.photoSources[0].assetId).toBe(original.nodes[0].assetId);
  // 模拟旧版已有的重复布局，验证不会自动清理用户内容。
  const copyId=randomUUID(),commandId=randomUUID();
  await rpc('canvas_execute',{request:{schemaVersion:3,commandId,idempotencyKey:commandId,projectId,boardId,baseRevision:original.board.revision,operations:[
    {opId:copyId,action:{type:'PlacePhoto',data:{boardId,assetId:original.nodes[0].assetId,x:original.nodes[0].x+260,y:original.nodes[0].y,width:220,height:160}}},
    {opId:randomUUID(),action:{type:'AddArrow',data:{boardId,fromNodeId:original.nodes[0].id,toNodeId:copyId}}},
  ]}});
  await page.reload();await page.getByRole('button',{name:'叙事画布',exact:true}).click();
  await expect(page.locator('.canvas-photo-node')).toHaveCount(2);
  await expect(page.locator('.canvas-board line')).toHaveCount(1);
  await page.locator('.canvas-photo-node').first().click();
  await page.locator('.canvas-photo-node').last().click({modifiers:['Shift']});
  await page.keyboard.press('Backspace');
  const confirmation=page.getByRole('dialog',{name:'移除选中内容',exact:true});await expect(confirmation).toBeVisible();
  await expect(page.locator('.canvas-photo-node')).toHaveCount(2);
  await confirmation.getByRole('button',{name:'移除选中内容',exact:true}).click();
  await expect(confirmation).toHaveCount(0);await expect(page.locator('.canvas-photo-node')).toHaveCount(0);await expect(page.locator('.canvas-board line')).toHaveCount(0);
  await page.getByRole('button',{name:'撤销',exact:true}).click();
  await expect(page.locator('.canvas-photo-node')).toHaveCount(2);await expect(page.locator('.canvas-board line')).toHaveCount(1);
  await page.getByRole('button',{name:'重做',exact:true}).click();await expect(page.locator('.canvas-photo-node')).toHaveCount(0);
  await page.getByRole('button',{name:'添加照片',exact:true}).click();await expect(picker.getByRole('checkbox').first()).toBeEnabled();
  await picker.getByRole('checkbox').first().check();await picker.getByRole('button',{name:'添加 1 张到画布',exact:true}).click();await expect(page.locator('.canvas-photo-node')).toHaveCount(1);
  await page.getByRole('button',{name:'添加照片',exact:true}).click();await expect(picker.getByRole('checkbox').first()).toBeDisabled();
  const directory=evidenceDirectory('canvas-photo-cleanup');await mkdir(directory,{recursive:true});await page.screenshot({path:resolve(directory,'already-on-canvas.png')});await picker.getByRole('button',{name:'取消',exact:true}).click();
  const after=await rpc<{photos:unknown[];sequence:string[]}>('get_project',{projectId});expect(after.photos).toEqual(before.photos);expect(after.sequence).toEqual(before.sequence);expect(await rpc('test_fixture_checksums')).toEqual(hashes);expect(errors).toEqual([]);expect(outside).toEqual([]);
});

