test('真实文字回执丢失：编辑保留、关闭后确认原请求、文字和历史不重复',async({page})=>{
  const {projectId,publicationId,dialog,hashes,errors,outside}=await prepare(page);let lost=false;const commands:string[]=[];
  await page.route(base+'/rpc',async route=>{const data=route.request().postDataJSON();if(data.command==='pub_execute'&&data.args.request.operations[0].action.type==='AddText'){commands.push(data.args.request.commandId);if(!lost){lost=true;const reply=await(await route.fetch()).json();expect(reply.ok).toBe(true);await route.fulfill({json:{ok:false,error:{code:'DATABASE',message:'lost after commit'}}});return;}}await route.fallback();});
  await dialog.getByRole('button',{name:'添加文字',exact:true}).click();const editor=page.getByRole('dialog',{name:'添加文字',exact:true});await editor.getByRole('textbox',{name:'文字内容',exact:true}).fill('只保存一次');await editor.getByRole('button',{name:'保存调整',exact:true}).click();await expect(editor.getByRole('button',{name:'保存调整',exact:true})).toBeDisabled();await expect(editor.getByRole('textbox',{name:'文字内容',exact:true})).toHaveValue('只保存一次');
  const saved=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId});expect(saved.layout.pages[0].texts).toHaveLength(1);await editor.getByRole('button',{name:'关闭对话框',exact:true}).click();await expect(editor).toHaveCount(0);await dialog.getByRole('button',{name:'确认上次保存',exact:true}).click();await expect(dialog.getByRole('status',{name:'版面状态',exact:true})).toHaveText('已确认保存结果');
  expect(commands).toHaveLength(2);expect(commands[1]).toBe(commands[0]);expect(await rpc('pub_layout',{projectId,publicationId})).toEqual(saved);expect(await rpc('test_fixture_checksums')).toEqual(hashes);expect(errors).toEqual([]);expect(outside).toEqual([]);
});

