test('真实照片版本回执丢失：不重复切换，返回后仅确认原请求',async({page})=>{
  const {projectId,publicationId,dialog,hashes,errors,outside}=await prepare(page);const before=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId}),frame=before.layout.pages[0].frames[0];await rpc('test_publication_versions',{projectId,publicationId,frameId:frame.id});let lost=false;const requests:unknown[]=[];
  await page.route(base+'/rpc',async route=>{const data=route.request().postDataJSON();if(data.command==='pub_execute'&&data.args.request.operations[0].action.type==='UpdateFrame'){requests.push(data.args.request);if(!lost){lost=true;const reply=await(await route.fetch()).json();expect(reply.ok).toBe(true);await route.fulfill({json:{ok:false,error:{code:'DATABASE',message:'lost after commit'}}});return;}}await route.fallback();});
  await dialog.getByRole('button',{name:'选择照片框 1',exact:true}).click();await dialog.getByRole('button',{name:'图像版本',exact:true}).click();const picker=page.getByRole('dialog',{name:'图像版本',exact:true});await picker.getByRole('radio',{name:/^Capture One/}).check();await expect.poll(()=>picker.getByRole('img',{name:'预览版本',exact:true}).evaluate((node:HTMLImageElement)=>node.complete&&node.naturalWidth>0)).toBe(true);await picker.getByRole('button',{name:'使用此版本',exact:true}).click();await expect(picker.getByRole('button',{name:'使用此版本',exact:true})).toBeDisabled();await expect(picker.getByRole('radio',{name:/^原片/})).toBeDisabled();const saved=await rpc('pub_layout',{projectId,publicationId}),history=await rpc('pub_versions',{projectId,publicationId,before:null});await picker.getByRole('button',{name:'返回',exact:true}).click();await expect(picker).toHaveCount(0);await dialog.getByRole('button',{name:'确认上次保存',exact:true}).click();await expect(dialog.locator('.publication-studio-notice')).toHaveText('已确认保存结果');expect(requests).toHaveLength(2);expect(requests[0]).toEqual(requests[1]);expect(await rpc('pub_layout',{projectId,publicationId})).toEqual(saved);expect(await rpc('pub_versions',{projectId,publicationId,before:null})).toEqual(history);expect(await rpc('test_fixture_checksums')).toEqual(hashes);expect(errors).toEqual([]);expect(outside).toEqual([]);
});

