test('排版辅助保存中断：重新打开只确认同一份本页设置，未重复历史或几何',async({page})=>{
 const {projectId,publicationId,dialog,hashes,errors,outside}=await prepare(page),before=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId});let lost=false;const requests:unknown[]=[];await page.route(base+'/rpc',async route=>{const data=route.request().postDataJSON();if(data.command==='pub_execute'&&data.args.request.operations[0].action.type==='SetPageGuides'){requests.push(data.args.request);if(!lost){lost=true;const reply=await(await route.fetch()).json();expect(reply.ok).toBe(true);await route.fulfill({json:{ok:false,error:{code:'DATABASE',message:'lost after commit'}}});return;}}await route.fallback();});
 await dialog.locator('.publication-guide-controls summary').click();await dialog.getByRole('button',{name:'网格与参考线',exact:true}).click();const editor=page.getByRole('dialog',{name:'网格与参考线',exact:true});await editor.getByRole('button',{name:'添加竖向参考线',exact:true}).click();await editor.getByRole('spinbutton',{name:'竖向参考线 1（mm）',exact:true}).fill('35');await editor.getByRole('button',{name:'保存本页设置',exact:true}).click();await expect(editor.getByRole('button',{name:'保存本页设置',exact:true})).toBeDisabled();await expect(editor.getByRole('status')).toContainText('确认');const saved=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId}),history=await rpc('pub_versions',{projectId,publicationId,before:null});expect(saved.layout.pages[0].frames).toEqual(before.layout.pages[0].frames);await editor.getByRole('button',{name:'返回',exact:true}).click();await dialog.getByRole('button',{name:'关闭对话框',exact:true}).click();await page.reload();await page.getByRole('button',{name:'出版物',exact:true}).click();await page.getByRole('button',{name:'确认上次保存',exact:true}).click();await expect(page.getByRole('button',{name:'确认上次保存',exact:true})).toHaveCount(0);expect(requests).toHaveLength(2);expect(requests[1]).toEqual(requests[0]);expect(await rpc('pub_layout',{projectId,publicationId})).toEqual(saved);expect(await rpc('pub_versions',{projectId,publicationId,before:null})).toEqual(history);await page.getByRole('button',{name:'版面与版本',exact:true}).click();await dialog.locator('.publication-guide-controls summary').click();await dialog.getByRole('button',{name:'网格与参考线',exact:true}).click();await expect(editor.getByRole('spinbutton',{name:'竖向参考线 1（mm）',exact:true})).toHaveValue('35');expect(await rpc('test_fixture_checksums')).toEqual(hashes);expect(errors).toEqual([]);expect(outside).toEqual([]);
});

