async function markPublicationChapters(page:Page,dialog:Locator,projectId:string,publicationId:string,secondStartId?:string){
  const before=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId});
  await dialog.getByRole('button',{name:'管理章节',exact:true}).click();const manager=page.getByRole('dialog',{name:'管理章节',exact:true});
  await manager.getByRole('button',{name:'从现有页面开始一章',exact:true}).click();await manager.getByRole('textbox',{name:'章节名称',exact:true}).nth(0).fill('夜行');
  await manager.getByRole('button',{name:'从现有页面开始一章',exact:true}).click();await manager.getByRole('textbox',{name:'章节名称',exact:true}).nth(1).fill('归途');await manager.getByRole('combobox',{name:'起始页',exact:true}).nth(1).selectOption(secondStartId??before.layout.pages[3].id);
  expect(await rpc('pub_layout',{projectId,publicationId})).toEqual(before);
  await manager.getByRole('button',{name:'保存章节调整',exact:true}).click();await expect(manager).toHaveCount(0);
  await expect(dialog.getByRole('status',{name:'版面状态',exact:true})).toHaveText('章节调整已保存。');
  return rpc<PublicationDocument>('pub_layout',{projectId,publicationId});
}

