async function preparePublicationSpine(page:Page,dialog:Locator){
 await dialog.getByRole('button',{name:'封面与书脊',exact:true}).click();const cover=page.getByRole('dialog',{name:'封面与书脊',exact:true});await cover.getByRole('spinbutton',{name:'书脊宽度（mm）',exact:true}).fill('10');await cover.getByRole('button',{name:'保存调整',exact:true}).click();await expect(cover).toHaveCount(0);
 await dialog.getByRole('button',{name:'添加文字',exact:true}).click();const editor=page.getByRole('dialog',{name:'添加文字',exact:true});
 for(const [name,value] of [['左侧位置（mm）','212'],['顶部位置（mm）','40'],['宽度（mm）','6'],['高度（mm）','200'],['字号（pt）','10'],['行距倍数','1.2']])await editor.getByRole('spinbutton',{name,exact:true}).fill(value);
 await editor.getByRole('textbox',{name:'文字内容',exact:true}).fill('FOCALROOM · NIGHT WALK');
 return editor;
}
