 await editor.getByRole('spinbutton',{name:'字号（pt）',exact:true}).fill('10');await editor.getByRole('spinbutton',{name:'高度（mm）',exact:true}).fill('200');await mode.selectOption('rotate-90');await expect(editor.locator('.publication-overflow-notice')).toHaveCount(0);await page.screenshot({path:resolve(directory,'spine-text-preview.png')});await page.setViewportSize({width:1024,height:768});await expect(editor.getByRole('button',{name:'保存调整',exact:true})).toBeInViewport();await expect.poll(()=>body.evaluate(element=>parseFloat(getComputedStyle(element).fontSize))).toBeCloseTo(13.333,1);await page.screenshot({path:resolve(directory,'spine-text-compact.png')});await page.setViewportSize({width:1440,height:1000});await editor.getByRole('button',{name:'保存调整',exact:true}).click();await expect(editor).toHaveCount(0);
 const saved=await rpc<PublicationDocument>('pub_layout',{projectId,publicationId}),text=saved.layout.pages[0].texts[0];expect(JSON.parse(text.styleJson!).textDirection).toBe('rotate-90');expect(text).toMatchObject({xMm:212,yMm:40,widthMm:6,heightMm:200});expect(saved.layout.pages.map(p=>p.frames)).toEqual(before.layout.pages.map(p=>p.frames));
